"""Regression coverage for declaration defaults in Maybe deciders."""

import pytest

import factory


@pytest.mark.parametrize('chance, expected', [(0, 'no'), (100, 'yes')])
@pytest.mark.parametrize('locale', [None, 'fr_FR'])
def test_faker_decider_defaults(chance, expected, locale):
    class ExampleFactory(factory.DictFactory):
        result = factory.Maybe(
            factory.Faker('boolean', chance_of_getting_true=chance, locale=locale),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert ExampleFactory()['result'] == expected


def test_faker_decider_unrolls_defaults():
    class ExampleFactory(factory.DictFactory):
        result = factory.Maybe(
            factory.Faker(
                'boolean',
                chance_of_getting_true=factory.LazyFunction(lambda: 100),
            ),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert ExampleFactory()['result'] == 'yes'


def test_nested_maybe_decider():
    class ExampleFactory(factory.DictFactory):
        result = factory.Maybe(
            factory.Maybe(factory.LazyFunction(lambda: True), True, False),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert ExampleFactory()['result'] == 'yes'


def test_overrides_apply_to_selected_branch_only():
    class ExampleFactory(factory.DictFactory):
        result = factory.Maybe(
            factory.Faker('boolean', chance_of_getting_true=100),
            yes_declaration=factory.Faker('pyint', min_value=1, max_value=1),
            no_declaration=0,
        )

    assert ExampleFactory(result__min_value=5, result__max_value=5)['result'] == 5
